28	        : ni(ni), start_i(start_i), data(new T[ni]), ownsData(true) {
29	        size_t idx = 0;
30	        for (T value : values) {
31	            if (idx < ni) {
32	                data[idx++] = value;
33	            }
34	        }
35	    }
36	
